      recibo: { record: { projectKind: 'software', goal: 'x', softwareScope: 'small', technicalLevel: 'mixed', accompaniment: 'L2', targets: ['claude'] } },
      railes: { habilidadPropia: true, perfil: true, nombres: { arnes: 'X' } }, claves: null,
