    const roto = fs.mkdtempSync(path.join(os.tmpdir(), 'rama-roto-'));
    fs.writeFileSync(path.join(roto, '.rsc.json'), '<<<<<<< HEAD\n{"version":1}\n=======\n');
    vscode.guion.raiz = roto;
