    rscM.arreglarEnSeco = async () => ({ codigo: 0, salida: 'Nothing to repair' });
    rscM.reevaluar = async () => ({ codigo: 0, salida: 'RSC_REASSESSMENT_NO_CHANGE' });
    rscM.revisar = async () => ({ codigo: 0, salida: '' });
